import{_ as i,b as t,c as e,g as a}from"./chunks/framework.86O3EbG5.js";const d=JSON.parse(`{"title":"DON'T MKAE ME THINK","description":"","frontmatter":{"title":"DON'T MKAE ME THINK","author":"oasis","date":"2025-02-08T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/dontmakemethink/1.md","filePath":"articles/books/dontmakemethink/1.md"}`),o={name:"articles/books/dontmakemethink/1.md"};function s(r,l,n,_,p,u){return t(),e("div",null,[...l[0]||(l[0]=[a("<p>花了几天时间读完了这本书，作者的所有设计策略和设计步骤都建立在“别让我思考”这一定律的基础上。此书的开篇就引入了这一定律。在这个基础上进行展开，阐述了为什么别让我思考是有效的定律，作者的分析过程是从我们如何浏览 web 页面开始的。作者认为当下的人们以扫描替代了阅读。 在这个论点的基础上，作者引入了广告设计的 101 原则，其内容如下：</p><ul><li>遵循习惯和管理</li><li>页面的视觉层次应该清晰 <ul><li>越重要的部分应该越突出</li><li>逻辑上相关的部分视觉上也应该相关</li><li>逻辑上包含的部分视觉上应该进行嵌套</li></ul></li><li>页面应该划分为明确定义的区域</li><li>可以点击的地方应该更明显</li><li>降低视觉噪声 <ul><li>主要有三类视觉噪声：眼花缭乱、组织不当、太过密集。</li></ul></li><li>为文本设计合适的格式 <ul><li>字体应该具有对比</li><li>充分使用标题</li><li>保持段落简洁</li><li>实用符号列表</li><li>突出关键词语</li></ul></li><li>有效的分类</li><li>有效的导航</li></ul><p>除上述这些原则外，在移动设计部分中关于好感读的部分我很感兴趣。有时候在浏览一些网站的时候，会感到很愤怒，血压飙升。原来这是在降低用户的好感度，好感度虽然可能被降为 0 ，但是有时候一个功能却能直接把好感度从 0 拉升到 100。 作者总结了降低好感度的几种方式：</p><ul><li>隐藏我想要的信息</li><li>因为没有按照你们的方式行事而惩罚我</li><li>想我询问不必要的信息</li><li>敷衍我，欺骗我</li><li>给我设置障碍</li><li>你的网站看上去不专业</li></ul><p>提升好感度的几种方式：</p><ul><li>知道人们在你网站上想做什么，并让它们明白简易</li><li>告诉我我想知道的</li><li>尽量减少步骤</li><li>知道我有哪些疑问，并且给予解答</li></ul><p>关于好感度的概念让我有一种感想，上面的这些情况每天都在发生，但是我们身临其境，却无法将这些情况提炼成概念。我想这可能是因为在身临其境的场景中，无法跳脱场景进行观察，同时也不具备观察自己行为和思维的能力。在未来的时日里，应该逐步锻炼跳脱场景，观察自己的行为和思维。</p>",7)])])}const m=i(o,[["render",s]]);export{d as __pageData,m as default};
